constexpr uint32_t kModelCount = 890u;
constexpr uint32_t kHashCount = 4568u;

inline bool LookupMetaOutfits(uint32_t modelHash,
                                const uint32_t** hashes,
                                uint16_t* count)
{
    uint32_t lo = 0;
    uint32_t hi = kModelCount;
    while (lo < hi)
    {
        const uint32_t mid = (lo + hi) / 2;
        if (kModels[mid].modelHash < modelHash)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo >= kModelCount || kModels[lo].modelHash != modelHash)
        return false;
    *hashes = &kOutfitHashes[kModels[lo].first];
    *count = kModels[lo].count;
    return true;
}

